create table if not exists public.merchant_attendance_cycle_intents(
 merchant_id text not null,intent_id uuid not null,worker_id uuid not null,employee_id uuid not null,employee_auth_user_id uuid not null,
 actor_auth_user_id uuid not null,access text not null,grant_id uuid,anchor_date date not null,from_date date not null,through_date date not null,
 time_zone text not null,start_at timestamptz not null,end_at timestamptz not null,due_at timestamptz not null,frame_key text not null,
 source_ref jsonb not null,activation_revision bigint not null,preparation_fingerprint text not null,intent_fingerprint text not null,
 accept_query jsonb not null,accept_command jsonb not null,recorded_at timestamptz not null,
 constraint merchant_attendance_cycle_intents_pk primary key(merchant_id,intent_id),
 constraint merchant_attendance_cycle_intents_merchant_fk foreign key(merchant_id) references public.merchants(id),
 constraint merchant_attendance_cycle_intents_worker_fk foreign key(merchant_id,worker_id) references public.merchant_attendance_workers(merchant_id,id),
 constraint merchant_attendance_cycle_intents_employee_fk foreign key(merchant_id,employee_id) references public.merchant_enterprise_employees(merchant_id,id),
 constraint merchant_attendance_cycle_intents_access_ck check((access='owner' and grant_id is null) or (access='delegate' and grant_id is not null)),
 constraint merchant_attendance_cycle_intents_frame_ck check(from_date>=date '2000-01-01' and through_date<=date '2100-12-31' and through_date-from_date between 0 and 30 and anchor_date between from_date and through_date and start_at<end_at and due_at=end_at),
 constraint merchant_attendance_cycle_intents_hash_ck check(frame_key~'^[0-9a-f]{64}$' and preparation_fingerprint~'^[0-9a-f]{64}$' and intent_fingerprint~'^[0-9a-f]{64}$' and activation_revision between 1 and 9007199254740989),
 constraint merchant_attendance_cycle_intents_bytes_ck check(octet_length(convert_to(source_ref::text,'UTF8'))<=16384 and octet_length(convert_to(accept_query::text,'UTF8'))<=4096 and octet_length(convert_to(accept_command::text,'UTF8'))<=8192)
);
create table if not exists public.merchant_attendance_cycle_operations(
