 constraint merchant_attendance_cycle_operations_revision_uq unique(merchant_id,intent_id,revision),
 constraint merchant_attendance_cycle_operations_frame_uq unique(merchant_id,worker_id,frame_key,frame_revision),
 constraint merchant_attendance_cycle_operations_action_ck check((action='accept' and revision=1 and operation_id=intent_id and period_id is null and send_operation_id is null) or (action='cancel' and revision=2 and period_id is null and send_operation_id is null) or (action='link' and revision=2 and period_id is not null and send_operation_id=operation_id)),
 constraint merchant_attendance_cycle_operations_shape_ck check(frame_revision between 1 and 9007199254740989 and frame_key~'^[0-9a-f]{64}$' and command_fingerprint~'^[0-9a-f]{64}$' and octet_length(convert_to(query::text,'UTF8'))<=4096 and octet_length(convert_to(command::text,'UTF8'))<=16384)
);
create table if not exists public.merchant_attendance_cycle_frame_heads(
 merchant_id text not null,worker_id uuid not null,frame_key text not null,from_date date not null,through_date date not null,time_zone text not null,
 start_at timestamptz not null,end_at timestamptz not null,revision bigint not null,last_operation_id uuid not null,active_intent_id uuid,
 constraint merchant_attendance_cycle_frame_heads_pk primary key(merchant_id,worker_id,frame_key),
 constraint merchant_attendance_cycle_frame_heads_worker_fk foreign key(merchant_id,worker_id) references public.merchant_attendance_workers(merchant_id,id),
 constraint merchant_attendance_cycle_frame_heads_operation_fk foreign key(merchant_id,last_operation_id) references public.merchant_attendance_cycle_operations(merchant_id,operation_id) deferrable initially deferred,
 constraint merchant_attendance_cycle_frame_heads_intent_fk foreign key(merchant_id,active_intent_id) references public.merchant_attendance_cycle_intents(merchant_id,intent_id) deferrable initially deferred,
 constraint merchant_attendance_cycle_frame_heads_frame_ck check(from_date>=date '2000-01-01' and through_date<=date '2100-12-31' and through_date-from_date between 0 and 30 and start_at<end_at and frame_key~'^[0-9a-f]{64}$' and revision between 1 and 9007199254740989)
);
create table if not exists public.merchant_attendance_period_cycle_adoptions(
 merchant_id text not null,intent_id uuid not null,period_id uuid not null,send_operation_id uuid not null,artifact_id uuid not null,
 actor_auth_user_id uuid not null,query jsonb not null,command jsonb not null,intent jsonb not null,command_fingerprint text not null,
 source_fingerprint text not null,artifact_sha256 text not null,recorded_at timestamptz not null,
 constraint merchant_attendance_period_cycle_adoptions_pk primary key(merchant_id,intent_id),
 constraint merchant_attendance_period_cycle_adoptions_period_uq unique(merchant_id,period_id),
 constraint merchant_attendance_period_cycle_adoptions_operation_uq unique(merchant_id,send_operation_id),
 constraint merchant_attendance_period_cycle_adoptions_intent_fk foreign key(merchant_id,intent_id) references public.merchant_attendance_cycle_intents(merchant_id,intent_id),
 constraint merchant_attendance_period_cycle_adoptions_period_fk foreign key(merchant_id,period_id) references public.merchant_attendance_period_closures(merchant_id,period_id),
 constraint merchant_attendance_period_cycle_adoptions_operation_fk foreign key(merchant_id,send_operation_id) references public.merchant_attendance_period_entries(merchant_id,operation_id),
 constraint merchant_attendance_period_cycle_adoptions_shape_ck check(command_fingerprint~'^[0-9a-f]{64}$' and source_fingerprint~'^[0-9a-f]{64}$' and artifact_sha256~'^[0-9a-f]{64}$' and octet_length(convert_to(query::text,'UTF8'))<=4096 and octet_length(convert_to(command::text,'UTF8'))<=4096 and octet_length(convert_to(intent::text,'UTF8'))<=1024)
);
create index if not exists merchant_attendance_cycle_active_frames_idx on public.merchant_attendance_cycle_frame_heads(merchant_id,worker_id,start_at,end_at) where active_intent_id is not null;
create index if not exists merchant_attendance_cycle_intents_worker_idx on public.merchant_attendance_cycle_intents(merchant_id,worker_id,intent_id);
alter table public.merchant_attendance_cycle_intents enable row level security;
alter table public.merchant_attendance_cycle_operations enable row level security;
alter table public.merchant_attendance_cycle_frame_heads enable row level security;
alter table public.merchant_attendance_period_cycle_adoptions enable row level security;
-- Revoke the bootstrap role only when it is not the private table owner.
do $pilot_private_table_bootstrap_acl$
declare target regclass;
begin
  for target in
    select c.oid::regclass from pg_catalog.pg_class c
    where c.oid=any(array[
      'public.merchant_attendance_cycle_intents'::regclass,
      'public.merchant_attendance_cycle_operations'::regclass,
      'public.merchant_attendance_cycle_frame_heads'::regclass,
      'public.merchant_attendance_period_cycle_adoptions'::regclass
    ]) and c.relowner<>(select oid from pg_catalog.pg_roles where rolname='postgres')
  loop
    execute format('revoke all privileges on table %s from postgres',target);
  end loop;
end;
$pilot_private_table_bootstrap_acl$;

revoke all on public.merchant_attendance_cycle_intents,public.merchant_attendance_cycle_operations,public.merchant_attendance_cycle_frame_heads,public.merchant_attendance_period_cycle_adoptions from public,anon,authenticated,service_role;

create or replace function public.faolla_attendance_cycle_hash_v1(p jsonb)
returns text language sql immutable set search_path=pg_catalog as $$
 select encode(sha256(convert_to(p::text,'UTF8')),'hex');
$$;
create or replace function public.faolla_attendance_cycle_stamp_v1(p timestamptz)
returns text language sql immutable set search_path=pg_catalog as $$
 select to_char(p at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
$$;
create or replace function public.faolla_attendance_cycle_frame_key_v1(p_worker uuid,p_from date,p_through date,p_zone text,p_start timestamptz,p_end timestamptz)
returns text language sql immutable set search_path=pg_catalog as $$
 select public.faolla_attendance_cycle_hash_v1(jsonb_build_array('attendance-cycle-frame-v1',p_worker,p_from,p_through,p_zone,public.faolla_attendance_cycle_stamp_v1(p_start),public.faolla_attendance_cycle_stamp_v1(p_end)));
$$;
create or replace function public.faolla_attendance_cycle_query_v1(p jsonb)
returns jsonb language plpgsql stable set search_path=pg_catalog as $$
declare k text;m text;keys text[];
begin
 m:=p->>'mode';keys:=array['siteId','access','workerId','grantId','mode']||case m when 'prepare' then array['anchorDate'] when 'list' then array['cursor'] when 'detail' then array['intentId'] when 'recover' then array['intentId','operationId'] else array[]::text[] end;
 if m not in('prepare','list','detail','recover') or public.faolla_attendance_operational_rule_object_v1(p,keys) is distinct from true
  or octet_length(convert_to(p::text,'UTF8'))>4096 or jsonb_typeof(p->'siteId') is distinct from 'string' or length(p->>'siteId')<>8 or (p->>'siteId')!~'^[0-9]{8}$'
  or p->>'access' not in('owner','delegate') or jsonb_typeof(p->'access') is distinct from 'string' or jsonb_typeof(p->'mode') is distinct from 'string'
  or (p->>'access'='owner')<>(p->'grantId'='null'::jsonb) then raise exception 'attendance_invalid_request';end if;
 foreach k in array array['workerId','grantId','intentId','operationId','cursor'] loop
  if not(p?k) or k in('grantId','cursor') and p->k='null'::jsonb then continue;end if;
  if public.faolla_attendance_operational_rule_scalar_v1(p->k,'uuid') is distinct from true then raise exception 'attendance_invalid_request';end if;
 end loop;
 if m='prepare' and (jsonb_typeof(p->'anchorDate') is distinct from 'string' or length(p->>'anchorDate')<>10 or (p->>'anchorDate')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
  or (p->>'anchorDate')::date::text is distinct from p->>'anchorDate' or (p->>'anchorDate')::date not between date '2000-01-01' and date '2100-12-31') then raise exception 'attendance_invalid_request';end if;
 return p;
end;
$$;
create or replace function public.faolla_attendance_cycle_command_v1(p_query jsonb,p_actor uuid,p jsonb)
returns text language plpgsql stable set search_path=pg_catalog as $$
declare k text;a text;keys text[];t jsonb:='[]';
begin
 perform public.faolla_attendance_cycle_query_v1(p_query);
 a:=p->>'action';keys:=case a when 'accept' then array['action','operationId','intentId','anchorDate','fromDate','throughDate','employeeId','employeeAuthUserId','expectedWorkerVersion','expectedEmployeeVersion','expectedSettingsVersion','expectedActivationRevision','expectedPreparationFingerprint','expectedFrameRevision','expectedFrameHeadOperationId','reason']
  when 'cancel' then array['action','operationId','intentId','expectedRevision','expectedHeadOperationId','expectedIntentFingerprint','reason'] else array[]::text[] end;
 if p_actor is null or p_query->>'mode'<>'detail' or a not in('accept','cancel') or public.faolla_attendance_operational_rule_object_v1(p,keys) is distinct from true
  or octet_length(convert_to(p::text,'UTF8'))>8192 or p->'intentId' is distinct from p_query->'intentId'
  or jsonb_typeof(p->'reason') is distinct from 'string' or length(p->>'reason') not between 1 and 500 or p->>'reason' is distinct from btrim(p->>'reason') or (p->>'reason')~('['||chr(1)||'-'||chr(31)||chr(127)||'-'||chr(159)||']') then raise exception 'attendance_invalid_request';end if;
 foreach k in array keys loop
  if k in('operationId','intentId','employeeId','employeeAuthUserId','expectedHeadOperationId','expectedFrameHeadOperationId') then
   if k='expectedFrameHeadOperationId' and p->k='null'::jsonb then continue;end if;
   if public.faolla_attendance_operational_rule_scalar_v1(p->k,'uuid') is distinct from true then raise exception 'attendance_invalid_request';end if;
  elsif k in('expectedWorkerVersion','expectedEmployeeVersion','expectedSettingsVersion','expectedActivationRevision') then
   if public.faolla_attendance_operational_rule_scalar_v1(p->k,'positive') is distinct from true then raise exception 'attendance_invalid_request';end if;
  elsif k='expectedFrameRevision' then
   if public.faolla_attendance_operational_rule_scalar_v1(p->k,'revision') is distinct from true then raise exception 'attendance_invalid_request';end if;
  elsif k in('expectedPreparationFingerprint','expectedIntentFingerprint') then
   if public.faolla_attendance_operational_rule_scalar_v1(p->k,'hash') is distinct from true then raise exception 'attendance_invalid_request';end if;
  elsif k in('anchorDate','fromDate','throughDate') then
   if jsonb_typeof(p->k) is distinct from 'string' or length(p->>k)<>10 or (p->>k)!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or (p->>k)::date::text is distinct from p->>k
    or (p->>k)::date not between date '2000-01-01' and date '2100-12-31' then raise exception 'attendance_invalid_request';end if;
  end if;
 end loop;
 if a='accept' and (p->'operationId' is distinct from p->'intentId' or ((p->>'expectedFrameRevision')::bigint=0)<>(p->'expectedFrameHeadOperationId'='null'::jsonb)
  or (p->>'expectedFrameRevision')::bigint>=9007199254740989 or (p->>'throughDate')::date-(p->>'fromDate')::date not between 0 and 30
  or (p->>'anchorDate')::date not between (p->>'fromDate')::date and (p->>'throughDate')::date)
  or a='cancel' and (p->'expectedRevision' is distinct from '1'::jsonb or p->'expectedHeadOperationId' is distinct from p->'intentId' or p->'operationId'=p->'intentId') then raise exception 'attendance_invalid_request';end if;
 foreach k in array keys loop t:=t||jsonb_build_array(p->k);end loop;
 return public.faolla_attendance_cycle_hash_v1(jsonb_build_array('attendance-cycle-command-v1',jsonb_build_array(p_query->'siteId',p_query->'access',p_query->'workerId',p_query->'grantId',p_query->'mode',p_query->'intentId'),p_actor,t));
end;
$$;

create or replace function public.faolla_attendance_cycle_authority_v1(p_site text,p_access text,p_worker uuid,p_grant uuid,p_actor uuid,p_from date,p_through date,p_action text)
returns void language plpgsql volatile set search_path=pg_catalog as $$
begin
 if p_actor is null or p_access not in('owner','delegate') or p_action not in('view','send') then raise exception 'attendance_access_denied';end if;
 if p_access='owner' then
  perform 1 from public.merchants where id=p_site and user_id=p_actor for share;
  if not found or p_grant is not null then raise exception 'attendance_access_denied';end if;
  perform 1 from public.merchant_attendance_settings where merchant_id=p_site for update;
  if not found then raise exception 'attendance_settings_required';end if;
  if p_action='send' and not(select enabled from public.merchant_attendance_settings where merchant_id=p_site) then raise exception 'attendance_platform_paused';end if;
  perform 1 from public.merchant_attendance_workers where merchant_id=p_site and id=p_worker for update;
  if not found then raise exception 'attendance_worker_not_found';end if;
 else
  --185 validates the actual delegate, issuer, both identity epochs, explicit
  --actions and whole requested date range. Knowing the UUID grants nothing.
  perform public.faolla_attendance_period_delegation_guard_v1(p_site,p_grant,p_actor,p_action,p_worker,p_from,p_through,null,true);
 end if;
end;
$$;

create or replace function public.faolla_attendance_cycle_operation_proof_v1(p public.merchant_attendance_cycle_operations)
returns void language plpgsql stable set search_path=pg_catalog as $$
declare i public.merchant_attendance_cycle_intents%rowtype;previous public.merchant_attendance_cycle_operations%rowtype;a public.merchant_attendance_period_cycle_adoptions%rowtype;
 ent public.merchant_attendance_period_entries%rowtype;c public.merchant_attendance_period_closures%rowtype;v public.merchant_attendance_period_versions%rowtype;ar public.merchant_attendance_period_artifacts%rowtype;expected text;
begin
 select * into i from public.merchant_attendance_cycle_intents where merchant_id=p.merchant_id and intent_id=p.intent_id;
 if i.intent_id is null or row(p.worker_id,p.frame_key) is distinct from row(i.worker_id,i.frame_key) or p.recorded_at<i.recorded_at
  or p.query->>'siteId' is distinct from p.merchant_id or p.query->>'workerId' is distinct from p.worker_id::text then raise exception 'attendance_operational_cycle_invalid';end if;
 if p.frame_revision>1 then
  select * into previous from public.merchant_attendance_cycle_operations where merchant_id=p.merchant_id and worker_id=p.worker_id and frame_key=p.frame_key and frame_revision=p.frame_revision-1;
  if previous.operation_id is null or previous.recorded_at>p.recorded_at then raise exception 'attendance_operational_cycle_invalid';end if;
 end if;
 if p.action='accept' then
  if previous.action='accept' or p.actor_auth_user_id<>i.actor_auth_user_id or p.query is distinct from i.accept_query or p.command is distinct from i.accept_command
   or p.recorded_at<>i.recorded_at or (p.command->>'expectedFrameRevision')::bigint<>p.frame_revision-1
   or (p.command->>'expectedFrameHeadOperationId')::uuid is distinct from previous.operation_id then raise exception 'attendance_operational_cycle_invalid';end if;
  expected:=public.faolla_attendance_cycle_command_v1(p.query,p.actor_auth_user_id,p.command);
 elsif p.action='cancel' then
  if previous.action is distinct from 'accept' or previous.intent_id<>p.intent_id or p.command->>'expectedIntentFingerprint' is distinct from i.intent_fingerprint then raise exception 'attendance_operational_cycle_invalid';end if;
  expected:=public.faolla_attendance_cycle_command_v1(p.query,p.actor_auth_user_id,p.command);
 else
  if previous.action is distinct from 'accept' or previous.intent_id<>p.intent_id or p.actor_auth_user_id<>i.actor_auth_user_id then raise exception 'attendance_operational_cycle_invalid';end if;
  select * into a from public.merchant_attendance_period_cycle_adoptions where merchant_id=p.merchant_id and intent_id=p.intent_id;
  select * into ent from public.merchant_attendance_period_entries where merchant_id=p.merchant_id and operation_id=p.operation_id;
  select * into c from public.merchant_attendance_period_closures where merchant_id=p.merchant_id and period_id=p.period_id;
  select * into v from public.merchant_attendance_period_versions where merchant_id=p.merchant_id and period_id=p.period_id and version=1;
  select * into ar from public.merchant_attendance_period_artifacts where merchant_id=p.merchant_id and artifact_id=v.artifact_id;
  if a.intent_id is null or ent.operation_id is null or c.period_id is null or v.version is null or ar.artifact_id is null
   or row(a.period_id,a.send_operation_id,a.actor_auth_user_id,a.recorded_at,a.query,a.command,a.intent)
    is distinct from row(p.period_id,p.operation_id,p.actor_auth_user_id,p.recorded_at,p.query,p.command->'periodCommand',p.command->'intent')
   or row(ent.period_id,ent.revision,ent.version,ent.actor_auth_user_id,ent.action,ent.command,ent.recorded_at)
    is distinct from row(p.period_id,1,1,p.actor_auth_user_id,'send'::text,a.command,p.recorded_at)
   or row(c.worker_id,c.employee_id,c.employee_auth_user_id,c.from_date,c.through_date,c.time_zone,c.start_at,c.end_at)
    is distinct from row(i.worker_id,i.employee_id,i.employee_auth_user_id,i.from_date,i.through_date,i.time_zone,i.start_at,i.end_at)
   or v.operation_id<>p.operation_id or v.artifact_id<>a.artifact_id or ar.period_id<>p.period_id or ar.source_fingerprint<>a.source_fingerprint or ar.artifact_sha256<>a.artifact_sha256
   or a.intent is distinct from jsonb_build_object('intentId',i.intent_id,'expectedIntentFingerprint',i.intent_fingerprint)
   then raise exception 'attendance_operational_cycle_invalid';end if;
  expected:=public.faolla_attendance_cycle_send_hash_v1(a.query,p.actor_auth_user_id,a.command,a.intent);
  if expected is distinct from a.command_fingerprint then raise exception 'attendance_operational_cycle_invalid';end if;
 end if;
 if p.command_fingerprint is distinct from expected then raise exception 'attendance_operational_cycle_invalid';end if;
end;
$$;

create or replace function public.faolla_attendance_cycle_guard_v1()
returns trigger language plpgsql set search_path=pg_catalog as $$
begin
 if tg_op='TRUNCATE' or tg_op='DELETE' or tg_op='UPDATE' and tg_table_name<>'merchant_attendance_cycle_frame_heads' then raise exception 'attendance_append_only';end if;
 if tg_table_name='merchant_attendance_cycle_frame_heads' then
  if new.frame_key is distinct from public.faolla_attendance_cycle_frame_key_v1(new.worker_id,new.from_date,new.through_date,new.time_zone,new.start_at,new.end_at)
   or tg_op='INSERT' and new.revision<>1 then raise exception 'attendance_operational_cycle_invalid';end if;
  if tg_op='UPDATE' and (row(new.merchant_id,new.worker_id,new.frame_key,new.from_date,new.through_date,new.time_zone,new.start_at,new.end_at)
   is distinct from row(old.merchant_id,old.worker_id,old.frame_key,old.from_date,old.through_date,old.time_zone,old.start_at,old.end_at)
   or new.revision<>old.revision+1 or new.last_operation_id=old.last_operation_id) then raise exception 'attendance_operational_cycle_invalid';end if;
 end if;
 return new;
end;
$$;
create or replace function public.faolla_attendance_cycle_deferred_v1()
returns trigger language plpgsql security definer set search_path=pg_catalog as $$
declare op public.merchant_attendance_cycle_operations%rowtype;h public.merchant_attendance_cycle_frame_heads%rowtype;i public.merchant_attendance_cycle_intents%rowtype;expected text;
begin
 if tg_table_name='merchant_attendance_cycle_frame_heads' then
  select * into h from public.merchant_attendance_cycle_frame_heads where merchant_id=new.merchant_id and worker_id=new.worker_id and frame_key=new.frame_key;
  select * into op from public.merchant_attendance_cycle_operations where merchant_id=h.merchant_id and operation_id=h.last_operation_id;
  if op.operation_id is null or row(op.worker_id,op.frame_key,op.frame_revision) is distinct from row(h.worker_id,h.frame_key,h.revision)
   or h.active_intent_id is distinct from (case when op.action='accept' then op.intent_id else null::uuid end) then raise exception 'attendance_operational_cycle_invalid';end if;
 elsif tg_table_name='merchant_attendance_cycle_intents' then
  select * into op from public.merchant_attendance_cycle_operations where merchant_id=new.merchant_id and operation_id=new.intent_id;
  if op.action is distinct from 'accept' then raise exception 'attendance_operational_cycle_invalid';end if;
  perform public.faolla_attendance_cycle_intent_v1(new);
  expected:=public.faolla_attendance_cycle_hash_v1(jsonb_build_array('attendance-cycle-intent-v1',new.merchant_id,new.intent_id,new.actor_auth_user_id,new.access,new.grant_id,new.worker_id,new.employee_id,new.employee_auth_user_id,
   new.anchor_date,new.from_date,new.through_date,new.time_zone,public.faolla_attendance_cycle_stamp_v1(new.start_at),public.faolla_attendance_cycle_stamp_v1(new.end_at),public.faolla_attendance_cycle_stamp_v1(new.due_at),
   new.preparation_fingerprint,new.source_ref->'sourceFingerprint',op.command_fingerprint,public.faolla_attendance_cycle_stamp_v1(new.recorded_at)));
  if expected is distinct from new.intent_fingerprint then raise exception 'attendance_operational_cycle_invalid';end if;
 elsif tg_table_name='merchant_attendance_period_cycle_adoptions' then
  select * into op from public.merchant_attendance_cycle_operations where merchant_id=new.merchant_id and operation_id=new.send_operation_id;
  if op.action is distinct from 'link' or op.intent_id<>new.intent_id then raise exception 'attendance_operational_cycle_invalid';end if;
 else op:=new;end if;
 perform public.faolla_attendance_cycle_operation_proof_v1(op);
 -- Every new fact needs a current derived head, not merely a loose receipt.
 if not exists(select 1 from public.merchant_attendance_cycle_frame_heads x where x.merchant_id=op.merchant_id and x.worker_id=op.worker_id and x.frame_key=op.frame_key and x.revision>=op.frame_revision)
  then raise exception 'attendance_operational_cycle_invalid';end if;
 return new;
end;
$$;

create or replace function public.faolla_attendance_cycle_send_hash_v1(p_query jsonb,p_actor uuid,p_command jsonb,p_intent jsonb)
returns text language plpgsql stable set search_path=pg_catalog as $$
declare t jsonb;k text;
begin
 if p_actor is null or public.faolla_attendance_period_closure_command_v2(p_command) is distinct from true or p_command->>'action'<>'send'
  or p_command->'expectedRevision' is distinct from '0'::jsonb or p_command->'expectedVersion' is distinct from '0'::jsonb
  or p_query->>'mode'<>'detail' or p_query->'periodId' is distinct from p_command->'periodId' or p_query->'operationId' is distinct from 'null'::jsonb
  or p_query->'version' is distinct from 'null'::jsonb or p_query->'cursor' is distinct from 'null'::jsonb or p_query->>'access' not in('owner','delegate')
  or public.faolla_attendance_operational_rule_object_v1(p_query,array['siteId','access','workerId','fromDate','throughDate','mode','periodId','operationId','version','cursor']||(case when p_query->>'access'='delegate' then array['grantId'] else array[]::text[] end)) is distinct from true
  or public.faolla_attendance_operational_rule_object_v1(p_intent,array['intentId','expectedIntentFingerprint']) is distinct from true
  or public.faolla_attendance_operational_rule_scalar_v1(p_intent->'intentId','uuid') is distinct from true or public.faolla_attendance_operational_rule_scalar_v1(p_intent->'expectedIntentFingerprint','hash') is distinct from true then raise exception 'attendance_invalid_request';end if;
 perform public.faolla_attendance_cycle_query_v1(jsonb_build_object('siteId',p_query->'siteId','access',p_query->'access','workerId',p_query->'workerId',
  'grantId',p_query->'grantId','mode','detail','intentId',p_intent->'intentId'));
 foreach k in array array['fromDate','throughDate'] loop
  if jsonb_typeof(p_query->k) is distinct from 'string' or length(p_query->>k)<>10 or (p_query->>k)!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   or (p_query->>k)::date::text is distinct from p_query->>k or (p_query->>k)::date not between date '2000-01-01' and date '2100-12-31' then raise exception 'attendance_invalid_request';end if;
 end loop;
 if (p_query->>'throughDate')::date-(p_query->>'fromDate')::date not between 0 and 30 then raise exception 'attendance_invalid_request';end if;
 --The tuple owns the complete original request independently of object order;
 --the original writer's parser still independently validates the whole shape.
 t:=jsonb_build_array('attendance-cycle-send-v1',p_actor,
  jsonb_build_array(p_query->'siteId',p_query->'access',p_query->'workerId',p_query->'grantId',p_query->'fromDate',p_query->'throughDate',p_query->'mode',p_query->'periodId',p_query->'operationId',p_query->'version',p_query->'cursor'),
  jsonb_build_array(p_command->'action',p_command->'operationId',p_command->'periodId',p_command->'expectedRevision',p_command->'expectedVersion',p_command->'expectedFingerprint',p_command->'reason'),
  jsonb_build_array(p_intent->'intentId',p_intent->'expectedIntentFingerprint'));
 return public.faolla_attendance_cycle_hash_v1(t);
end;
$$;

create or replace function public.faolla_attendance_cycle_preparation_v1(p_source jsonb,p_anchor date,p_revision bigint,p_active boolean)
returns jsonb language plpgsql stable set search_path=pg_catalog as $$
declare layer_name text;v jsonb;choice jsonb:=jsonb_build_object('mode','inherit');state_name text;kind text;start_day date;end_day date;anchor date;
 choice_tuple jsonb;range_value jsonb:='null';range_tuple jsonb:='null';source_tuple jsonb;without_time jsonb;item jsonb;idx bigint;fingerprint text;zone text;
begin
 source_tuple:=public.faolla_attendance_operational_source_tuple_v1(p_source);
 if public.faolla_attendance_cycle_hash_v1(source_tuple) is distinct from p_source->>'sourceFingerprint' or p_revision not between 0 and 9007199254740989 or p_active is null or p_active and p_revision=0
  or p_anchor not between date '2000-01-01' and date '2100-12-31' then raise exception 'attendance_operational_cycle_invalid';end if;
 zone:=p_source->'settingsRef'->>'timeZone';
 if public.faolla_attendance_rule_day_start_v1(p_anchor::text,zone) is null then raise exception 'attendance_operational_cycle_invalid';end if;
 foreach layer_name in array array['personal','group','enterprise'] loop
  v:=p_source->'layers'->layer_name;if v='null'::jsonb then continue;end if;
  v:=v->'rules'->'timesheetCycle';if v->>'mode'<>'inherit' then choice:=v;exit;end if;
 end loop;
 kind:=choice->'value'->>'kind';
 state_name:=case when not p_active then 'consumer_disabled' when choice->>'mode'='inherit' then 'unconfigured' when choice->>'mode'='disabled' then 'disabled' when kind='manual' then 'manual' else 'ready' end;
 -- The pure calculator still validates its selected range even while off.
 if choice->>'mode'='value' and kind<>'manual' then
  if kind='weekly' then start_day:=p_anchor-((extract(isodow from p_anchor)::integer-(choice->'value'->>'weekStartsOn')::integer+7)%7);end_day:=start_day+6;
  elsif kind='fortnightly' then anchor:=(choice->'value'->>'anchorDate')::date;start_day:=anchor+(floor((p_anchor-anchor)::numeric/14)::integer*14);end_day:=start_day+13;
  elsif kind='monthly' then start_day:=make_date(extract(year from p_anchor)::integer,extract(month from p_anchor)::integer,1);end_day:=(start_day+interval '1 month')::date-1;
  else raise exception 'attendance_operational_cycle_invalid';end if;
  if start_day<date '2000-01-01' or end_day>date '2100-12-31' then raise exception 'attendance_operational_cycle_out_of_range';end if;
  if state_name='ready' then range_value:=jsonb_build_object('fromDate',start_day,'throughDate',end_day,'civilDays',end_day-start_day+1);range_tuple:=jsonb_build_array(start_day,end_day,end_day-start_day+1);end if;
 end if;
 choice_tuple:=case when choice->>'mode'<>'value' then jsonb_build_array(choice->'mode') when kind='weekly' then jsonb_build_array('value',kind,choice->'value'->'weekStartsOn')
  when kind='fortnightly' then jsonb_build_array('value',kind,choice->'value'->'anchorDate') else jsonb_build_array('value',kind) end;
 select jsonb_agg(x.value order by x.ordinality) into without_time from jsonb_array_elements(source_tuple) with ordinality x where x.ordinality<>4;
 fingerprint:=public.faolla_attendance_cycle_hash_v1(jsonb_build_array('attendance-cycle-preparation-v1',without_time,jsonb_build_array(p_revision,p_active),p_anchor,choice_tuple,state_name,range_tuple));
 return jsonb_build_object('protocol','attendance-cycle-preparation-v1','candidateOnly',true,'applied',false,'authorityChecked',false,'siteId',p_source->'siteId',
  'workerIdentity',p_source->'workerIdentity','observedAt',p_source->'at','settingsRef',p_source->'settingsRef','anchorDate',p_anchor,'activation',jsonb_build_object('revision',p_revision,'active',p_active),
  'choice',choice,'state',state_name,'range',range_value,'sourceFingerprint',p_source->'sourceFingerprint','preparationFingerprint',fingerprint);
end;
$$;

create or replace function public.faolla_attendance_cycle_receipt_v1(p public.merchant_attendance_cycle_operations)
returns jsonb language sql stable set search_path=pg_catalog as $$
 select jsonb_build_object('operationId',p.operation_id,'intentId',p.intent_id,'action',p.action,'actorId',p.actor_auth_user_id,'revision',p.revision,
  'recordedAt',public.faolla_attendance_cycle_stamp_v1(p.recorded_at),'commandFingerprint',p.command_fingerprint,'periodId',p.period_id,'sendOperationId',p.send_operation_id);
$$;
create or replace function public.faolla_attendance_cycle_intent_v1(p public.merchant_attendance_cycle_intents)
returns jsonb language plpgsql stable set search_path=pg_catalog as $$
declare src jsonb;prep jsonb;
begin
 src:=public.faolla_attendance_operational_punch_saved_source_v1(p.source_ref);
 prep:=public.faolla_attendance_cycle_preparation_v1(src,p.anchor_date,p.activation_revision,true);
 if prep->>'preparationFingerprint' is distinct from p.preparation_fingerprint or p.frame_key is distinct from public.faolla_attendance_cycle_frame_key_v1(p.worker_id,p.from_date,p.through_date,p.time_zone,p.start_at,p.end_at)
  or row(src->>'siteId',src->'workerIdentity'->>'workerId',src->'workerIdentity'->>'employeeId',src->'workerIdentity'->>'employeeAuthUserId',src->'settingsRef'->>'timeZone')
   is distinct from row(p.merchant_id,p.worker_id::text,p.employee_id::text,p.employee_auth_user_id::text,p.time_zone)
  or (src->>'at')::timestamptz>p.recorded_at or p.accept_command->'expectedPreparationFingerprint' is distinct from prep->'preparationFingerprint'
  or p.accept_command->'expectedWorkerVersion' is distinct from src->'workerIdentity'->'workerVersion' or p.accept_command->'expectedEmployeeVersion' is distinct from src->'workerIdentity'->'employeeVersion'
  or p.accept_command->'expectedSettingsVersion' is distinct from src->'settingsRef'->'version' or p.accept_command->'expectedActivationRevision' is distinct from prep->'activation'->'revision'
  or p.accept_command->>'employeeId' is distinct from p.employee_id::text or p.accept_command->>'employeeAuthUserId' is distinct from p.employee_auth_user_id::text
  or row(p.accept_command->>'anchorDate',p.accept_command->>'fromDate',p.accept_command->>'throughDate') is distinct from row(p.anchor_date::text,p.from_date::text,p.through_date::text)
  or prep->'range' is distinct from jsonb_build_object('fromDate',p.from_date,'throughDate',p.through_date,'civilDays',p.through_date-p.from_date+1) then raise exception 'attendance_operational_cycle_invalid';end if;
 return jsonb_build_object('intentId',p.intent_id,'workerId',p.worker_id,'employeeId',p.employee_id,'employeeAuthUserId',p.employee_auth_user_id,'actorId',p.actor_auth_user_id,'access',p.access,'grantId',p.grant_id,
  'anchorDate',p.anchor_date,'fromDate',p.from_date,'throughDate',p.through_date,'timeZone',p.time_zone,'fromAt',public.faolla_attendance_cycle_stamp_v1(p.start_at),'toAt',public.faolla_attendance_cycle_stamp_v1(p.end_at),
   'dueAt',public.faolla_attendance_cycle_stamp_v1(p.due_at),'source',src,'preparation',prep,'acceptCommand',p.accept_command,'intentFingerprint',p.intent_fingerprint,'recordedAt',public.faolla_attendance_cycle_stamp_v1(p.recorded_at));
end;
$$;

create or replace function public.faolla_attendance_operational_cycle_v1(p_query jsonb,p_auth_user_id uuid,p_command jsonb default null,p_allow_accept boolean default false)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare site text;access_name text;mode_name text;wid uuid;gid uuid;iid uuid;opid uuid;after_id uuid;next_id uuid;stamp timestamptz;request_hash text;
 i public.merchant_attendance_cycle_intents%rowtype;op public.merchant_attendance_cycle_operations%rowtype;head public.merchant_attendance_cycle_frame_heads%rowtype;
 activation public.merchant_attendance_operational_consumer_activations%rowtype;w public.merchant_attendance_workers%rowtype;e public.merchant_enterprise_employees%rowtype;
 source_value jsonb;prep jsonb;data_value jsonb;receipt_value jsonb;items jsonb:='[]';item_value jsonb;raw_value jsonb;frame_value jsonb;candidate public.merchant_attendance_cycle_intents%rowtype;
 from_day date;through_day date;start_at_value timestamptz;end_at_value timestamptz;zone text;frame_key_value text;intent_hash text;seen integer:=0;
begin
 perform public.faolla_attendance_cycle_query_v1(p_query);
 if p_auth_user_id is null or p_allow_accept is null then raise exception 'attendance_invalid_request';end if;
 site:=p_query->>'siteId';access_name:=p_query->>'access';mode_name:=p_query->>'mode';wid:=(p_query->>'workerId')::uuid;gid:=(p_query->>'grantId')::uuid;
 iid:=(p_query->>'intentId')::uuid;opid:=(p_query->>'operationId')::uuid;after_id:=(p_query->>'cursor')::uuid;
 if p_command is not null then request_hash:=public.faolla_attendance_cycle_command_v1(p_query,p_auth_user_id,p_command);opid:=(p_command->>'operationId')::uuid;end if;
 -- Immutable original-actor recovery is deliberately before today's settings,
 --employee status, grant and source. It never returns their current body.
 if opid is not null then
  select * into op from public.merchant_attendance_cycle_operations where merchant_id=site and operation_id=opid;
  if op.operation_id is not null then
   if op.actor_auth_user_id<>p_auth_user_id or op.intent_id<>iid or op.worker_id<>wid or op.action='link'
    or op.query->'access' is distinct from p_query->'access' or op.query->'grantId' is distinct from p_query->'grantId' then raise exception 'attendance_access_denied';end if;
   if p_command is not null and (op.query is distinct from p_query or op.command is distinct from p_command or op.command_fingerprint is distinct from request_hash) then raise exception 'attendance_operation_conflict';end if;
   perform public.faolla_attendance_cycle_operation_proof_v1(op);
   return jsonb_build_object('protocol','attendance-operational-cycle-v1','siteId',site,'actorId',p_auth_user_id,'readAt',public.faolla_attendance_cycle_stamp_v1(clock_timestamp()),'data',jsonb_build_object('kind','receipt'),'receipt',public.faolla_attendance_cycle_receipt_v1(op));
  end if;
 end if;
 if iid is not null then select * into i from public.merchant_attendance_cycle_intents where merchant_id=site and intent_id=iid;end if;
 if i.intent_id is not null and i.worker_id<>wid then raise exception 'attendance_access_denied';end if;
 if mode_name in('detail','recover') and p_command is null and mode_name='detail' and i.intent_id is null then raise exception 'attendance_operational_cycle_not_found';end if;
 if p_command->>'action'='cancel' and i.intent_id is null then raise exception 'attendance_operational_cycle_not_found';end if;
 --For a delegate's prepare, first qualify the anchor before reading 192;
 --then qualify the entire resulting candidate below. The singleton list probe
 --uses the actual grant's bounded saved range, never a guessed date policy.
 if mode_name='prepare' then from_day:=(p_query->>'anchorDate')::date;through_day:=from_day;
 elsif p_command->>'action'='accept' then from_day:=(p_command->>'fromDate')::date;through_day:=(p_command->>'throughDate')::date;
 elsif i.intent_id is not null then from_day:=i.from_date;through_day:=i.through_date;
 elsif access_name='delegate' then
  select from_date,through_date into from_day,through_day from public.merchant_attendance_period_delegations where merchant_id=site and grant_id=gid and worker_id=wid;
  if not found then raise exception 'attendance_access_denied';end if;
 else from_day:=date '2000-01-01';through_day:=from_day;end if;
 --185 permits a 366-day grant but each business range is at most31days. An
 --empty list/recovery qualifies a single saved grant day; bounded list rows
 --are then filtered against that same immutable grant's complete date frame.
 perform public.faolla_attendance_cycle_authority_v1(site,access_name,wid,gid,p_auth_user_id,from_day,
  (case when access_name='delegate' and i.intent_id is null and mode_name in('list','recover') then from_day else through_day end),
  (case when mode_name='prepare' or p_command->>'action'='accept' then 'send' else 'view' end));
 if access_name='delegate' and i.intent_id is not null and (i.actor_auth_user_id<>p_auth_user_id or i.access<>'delegate' or i.grant_id is distinct from gid) then raise exception 'attendance_access_denied';end if;
 if mode_name='recover' then data_value:=jsonb_build_object('kind','receipt');
 elsif mode_name='list' then
  for candidate in select x.* from public.merchant_attendance_cycle_intents x where x.merchant_id=site and x.worker_id=wid and (after_id is null or x.intent_id>after_id)
   and (access_name='owner' or x.access='delegate' and x.grant_id=gid and x.actor_auth_user_id=p_auth_user_id and x.from_date>=from_day and x.through_date<=through_day)
   order by x.intent_id limit 26 loop
   seen:=seen+1;if seen=26 then next_id:=(items->24->>'intentId')::uuid;exit;end if;
   select * into op from public.merchant_attendance_cycle_operations where merchant_id=site and intent_id=candidate.intent_id order by revision desc limit 1;
   perform public.faolla_attendance_cycle_operation_proof_v1(op);
   items:=items||jsonb_build_array(jsonb_build_object('intentId',candidate.intent_id,'actorId',candidate.actor_auth_user_id,'access',candidate.access,'grantId',candidate.grant_id,
    'employeeId',candidate.employee_id,'employeeAuthUserId',candidate.employee_auth_user_id,'anchorDate',candidate.anchor_date,'fromDate',candidate.from_date,'throughDate',candidate.through_date,
    'timeZone',candidate.time_zone,'fromAt',public.faolla_attendance_cycle_stamp_v1(candidate.start_at),'toAt',public.faolla_attendance_cycle_stamp_v1(candidate.end_at),'dueAt',public.faolla_attendance_cycle_stamp_v1(candidate.due_at),
    'intentFingerprint',candidate.intent_fingerprint,'head',public.faolla_attendance_cycle_receipt_v1(op)));
  end loop;
  data_value:=jsonb_build_object('kind','list','items',items,'nextCursor',next_id);
 elsif p_command is null and mode_name='detail' then
  select * into op from public.merchant_attendance_cycle_operations where merchant_id=site and intent_id=iid order by revision desc limit 1;
  perform public.faolla_attendance_cycle_operation_proof_v1(op);
  data_value:=jsonb_build_object('kind','detail','intent',public.faolla_attendance_cycle_intent_v1(i),'head',public.faolla_attendance_cycle_receipt_v1(op));
 elsif p_command->>'action'='cancel' then
  --Current canonical owner may close a predecessor owner's unlinked plan.
  --A delegate can close only their own still-authorized plan. Neither action
  --changes the immutable original acceptance or grants send rights.
  select * into head from public.merchant_attendance_cycle_frame_heads where merchant_id=site and worker_id=wid and frame_key=i.frame_key for update;
  if head.active_intent_id is distinct from iid or head.last_operation_id is distinct from (p_command->>'expectedHeadOperationId')::uuid
   or p_command->>'expectedIntentFingerprint' is distinct from i.intent_fingerprint or head.revision>=9007199254740989 then raise exception 'attendance_operational_cycle_changed';end if;
  stamp:=clock_timestamp();
  insert into public.merchant_attendance_cycle_operations values(site,opid,iid,wid,i.frame_key,'cancel',p_auth_user_id,2,head.revision+1,p_query,p_command,request_hash,null,null,stamp) returning * into op;
  update public.merchant_attendance_cycle_frame_heads set revision=head.revision+1,last_operation_id=opid,active_intent_id=null where merchant_id=site and worker_id=wid and frame_key=i.frame_key;
  receipt_value:=public.faolla_attendance_cycle_receipt_v1(op);data_value:=jsonb_build_object('kind','receipt');
 else
  --Only a current, authorized new preparation/accept reaches the private source.
  select * into w from public.merchant_attendance_workers where merchant_id=site and id=wid;
  select * into e from public.merchant_enterprise_employees where merchant_id=site and id=w.employee_id for share;
  if e.id is null or e.auth_user_id is null then raise exception 'attendance_period_identity_changed';end if;
  select * into activation from public.merchant_attendance_operational_consumer_activations where merchant_id=site and consumer='timesheet_cycle' order by revision desc limit 1;
  stamp:=clock_timestamp();if activation.recorded_at>stamp then raise exception 'attendance_operational_cycle_changed';end if;
  source_value:=public.faolla_attendance_operational_source_v1(site,wid,e.id,e.auth_user_id,stamp);
  prep:=public.faolla_attendance_cycle_preparation_v1(source_value,case when p_command is null then (p_query->>'anchorDate')::date else (p_command->>'anchorDate')::date end,coalesce(activation.revision,0),coalesce(activation.action='activate',false));
  if prep->>'state'='ready' then
   from_day:=(prep->'range'->>'fromDate')::date;through_day:=(prep->'range'->>'throughDate')::date;zone:=source_value->'settingsRef'->>'timeZone';
   perform public.faolla_attendance_cycle_authority_v1(site,access_name,wid,gid,p_auth_user_id,from_day,through_day,'send');
   start_at_value:=public.faolla_attendance_control_day_boundary_v1(from_day,zone);end_at_value:=public.faolla_attendance_control_day_boundary_v1(through_day+1,zone);
   if start_at_value>=end_at_value then raise exception 'attendance_operational_cycle_invalid';end if;
   frame_key_value:=public.faolla_attendance_cycle_frame_key_v1(wid,from_day,through_day,zone,start_at_value,end_at_value);
   select * into head from public.merchant_attendance_cycle_frame_heads where merchant_id=site and worker_id=wid and frame_key=frame_key_value for update;
   frame_value:=jsonb_build_object('revision',coalesce(head.revision,0),'lastOperationId',head.last_operation_id);
  end if;
  if p_command is null then
   data_value:=jsonb_build_object('kind','preparation','source',source_value,'anchorDate',p_query->'anchorDate','activation',jsonb_build_object('revision',coalesce(activation.revision,0),'active',coalesce(activation.action='activate',false)),'frameHead',frame_value);
  else
   if not p_allow_accept or prep->>'state'<>'ready' then raise exception 'attendance_operational_cycle_disabled';end if;
   if p_command->'employeeId' is distinct from source_value->'workerIdentity'->'employeeId' or p_command->'employeeAuthUserId' is distinct from source_value->'workerIdentity'->'employeeAuthUserId'
    or p_command->'expectedWorkerVersion' is distinct from source_value->'workerIdentity'->'workerVersion' or p_command->'expectedEmployeeVersion' is distinct from source_value->'workerIdentity'->'employeeVersion'
    or p_command->'expectedSettingsVersion' is distinct from source_value->'settingsRef'->'version' or p_command->'expectedActivationRevision' is distinct from prep->'activation'->'revision'
    or p_command->'expectedPreparationFingerprint' is distinct from prep->'preparationFingerprint' or p_command->'fromDate' is distinct from prep->'range'->'fromDate' or p_command->'throughDate' is distinct from prep->'range'->'throughDate'
    or (p_command->>'expectedFrameRevision')::bigint<>coalesce(head.revision,0) or (p_command->>'expectedFrameHeadOperationId')::uuid is distinct from head.last_operation_id
    or head.active_intent_id is not null then raise exception 'attendance_operational_cycle_changed';end if;
   --Only active heads and the existing period predecessor are examined, not
   --the unbounded cancelled/reaccepted intent history.
   if exists(select 1 from (select end_at from public.merchant_attendance_cycle_frame_heads x where x.merchant_id=site and x.worker_id=wid and x.active_intent_id is not null and x.start_at<end_at_value order by x.start_at desc limit 1) x where x.end_at>start_at_value)
    or exists(select 1 from (select end_at from public.merchant_attendance_period_closures x where x.merchant_id=site and x.worker_id=wid and x.start_at<end_at_value order by x.start_at desc,x.period_id desc limit 1) x where x.end_at>start_at_value)
    then raise exception 'attendance_period_overlap';end if;
   intent_hash:=public.faolla_attendance_cycle_hash_v1(jsonb_build_array('attendance-cycle-intent-v1',site,iid,p_auth_user_id,access_name,gid,wid,e.id,e.auth_user_id,p_command->'anchorDate',from_day,through_day,zone,
    public.faolla_attendance_cycle_stamp_v1(start_at_value),public.faolla_attendance_cycle_stamp_v1(end_at_value),public.faolla_attendance_cycle_stamp_v1(end_at_value),prep->'preparationFingerprint',source_value->'sourceFingerprint',request_hash,public.faolla_attendance_cycle_stamp_v1(stamp)));
   insert into public.merchant_attendance_cycle_intents values(site,iid,wid,e.id,e.auth_user_id,p_auth_user_id,access_name,gid,(p_command->>'anchorDate')::date,from_day,through_day,zone,start_at_value,end_at_value,end_at_value,frame_key_value,
    public.faolla_attendance_operational_punch_source_ref_v1(source_value),activation.revision,prep->>'preparationFingerprint',intent_hash,p_query,p_command,stamp) returning * into i;
   insert into public.merchant_attendance_cycle_operations values(site,opid,iid,wid,frame_key_value,'accept',p_auth_user_id,1,coalesce(head.revision,0)+1,p_query,p_command,request_hash,null,null,stamp) returning * into op;
   --The worker UPDATE lock serializes the absent-head case. Do not UPSERT:
   --PostgreSQL runs BEFORE INSERT even on a conflict, whereas a later frame
   --revision must run the strict existing-row UPDATE proof, not a revision1
   --INSERT path. This permits cancel/reaccept without weakening that guard.
   if head.frame_key is null then
    insert into public.merchant_attendance_cycle_frame_heads values(site,wid,frame_key_value,from_day,through_day,zone,start_at_value,end_at_value,1,opid,iid);
   else
    update public.merchant_attendance_cycle_frame_heads set revision=head.revision+1,last_operation_id=opid,active_intent_id=iid where merchant_id=site and worker_id=wid and frame_key=frame_key_value;
   end if;
   receipt_value:=public.faolla_attendance_cycle_receipt_v1(op);data_value:=jsonb_build_object('kind','receipt');
  end if;
 end if;
 return jsonb_build_object('protocol','attendance-operational-cycle-v1','siteId',site,'actorId',p_auth_user_id,'readAt',public.faolla_attendance_cycle_stamp_v1(clock_timestamp()),'data',data_value,'receipt',receipt_value);
end;
$$;

create or replace function public.faolla_attendance_cycle_gate_v1(p_site text,p_worker uuid,p_actor uuid,p_access text,p_grant uuid,p_from date,p_through date,p_source jsonb,p_intent jsonb)
returns void language plpgsql volatile set search_path=pg_catalog as $$
declare i public.merchant_attendance_cycle_intents%rowtype;h public.merchant_attendance_cycle_frame_heads%rowtype;active_revision bigint;active_action text;
begin
 if p_intent is null then
  --Legacy manual first sends are blocked only when overlapping a currently
  --active managed plan. Cancellation permits manual send without adoption.
  if exists(select 1 from (select end_at from public.merchant_attendance_cycle_frame_heads x where x.merchant_id=p_site and x.worker_id=p_worker and x.active_intent_id is not null
   and x.start_at<(p_source->>'toAt')::timestamptz order by x.start_at desc limit 1) x where x.end_at>(p_source->>'fromAt')::timestamptz) then raise exception 'attendance_operational_cycle_protocol_required';end if;
  return;
 end if;
 select * into i from public.merchant_attendance_cycle_intents where merchant_id=p_site and intent_id=(p_intent->>'intentId')::uuid;
 if i.intent_id is null then raise exception 'attendance_operational_cycle_not_found';end if;
 select * into h from public.merchant_attendance_cycle_frame_heads where merchant_id=p_site and worker_id=p_worker and frame_key=i.frame_key for update;
 select revision,action into active_revision,active_action from public.merchant_attendance_operational_consumer_activations where merchant_id=p_site and consumer='timesheet_cycle' order by revision desc limit 1;
 if active_action is distinct from 'activate' then raise exception 'attendance_operational_cycle_disabled';end if;
 if h.active_intent_id is distinct from i.intent_id or h.last_operation_id<>i.intent_id or h.revision>=9007199254740989
  or i.actor_auth_user_id<>p_actor or i.access<>p_access or i.grant_id is distinct from p_grant or i.worker_id<>p_worker or i.from_date<>p_from or i.through_date<>p_through
  or p_intent->>'expectedIntentFingerprint' is distinct from i.intent_fingerprint
  or not exists(select 1 from public.merchant_attendance_workers w join public.merchant_enterprise_employees e on e.merchant_id=w.merchant_id and e.id=w.employee_id
   where w.merchant_id=p_site and w.id=p_worker and w.employee_id=i.employee_id and e.auth_user_id=i.employee_auth_user_id)
  or row(i.time_zone,i.start_at,i.end_at) is distinct from row(p_source->>'timeZone',(p_source->>'fromAt')::timestamptz,(p_source->>'toAt')::timestamptz)
  then raise exception 'attendance_operational_cycle_changed';end if;
 --Acceptance's source is immutable. Today's cycle choice is not resampled;
 --only current send authority/activation and exact original frame are required.
 perform public.faolla_attendance_cycle_intent_v1(i);
end;
$$;

create or replace function public.faolla_attendance_cycle_link_v1(p_query jsonb,p_actor uuid,p_command jsonb,p_intent jsonb)
returns void language plpgsql volatile set search_path=pg_catalog as $$
declare i public.merchant_attendance_cycle_intents%rowtype;h public.merchant_attendance_cycle_frame_heads%rowtype;ent public.merchant_attendance_period_entries%rowtype;
 ar public.merchant_attendance_period_artifacts%rowtype;v public.merchant_attendance_period_versions%rowtype;op public.merchant_attendance_cycle_operations%rowtype;fp text;site text;
begin
 if p_intent is null then return;end if;
 fp:=public.faolla_attendance_cycle_send_hash_v1(p_query,p_actor,p_command,p_intent);site:=p_query->>'siteId';
 select * into i from public.merchant_attendance_cycle_intents where merchant_id=site and intent_id=(p_intent->>'intentId')::uuid;
 select * into h from public.merchant_attendance_cycle_frame_heads where merchant_id=site and worker_id=i.worker_id and frame_key=i.frame_key for update;
 select * into ent from public.merchant_attendance_period_entries where merchant_id=site and operation_id=(p_command->>'operationId')::uuid;
 select * into v from public.merchant_attendance_period_versions where merchant_id=site and period_id=ent.period_id and version=1;
 select * into ar from public.merchant_attendance_period_artifacts where merchant_id=site and artifact_id=v.artifact_id;
 if i.intent_id is null or h.active_intent_id is distinct from i.intent_id or ent.operation_id is null or ent.action<>'send' or ent.revision<>1 or ent.version<>1
  or ent.actor_auth_user_id<>p_actor or ent.command is distinct from p_command or v.operation_id<>ent.operation_id or ar.artifact_id is null then raise exception 'attendance_operational_cycle_invalid';end if;
 insert into public.merchant_attendance_period_cycle_adoptions values(site,i.intent_id,ent.period_id,ent.operation_id,ar.artifact_id,p_actor,p_query,p_command,p_intent,fp,ar.source_fingerprint,ar.artifact_sha256,ent.recorded_at);
 insert into public.merchant_attendance_cycle_operations values(site,ent.operation_id,i.intent_id,i.worker_id,i.frame_key,'link',p_actor,2,h.revision+1,p_query,jsonb_build_object('periodCommand',p_command,'intent',p_intent),fp,ent.period_id,ent.operation_id,ent.recorded_at) returning * into op;
 update public.merchant_attendance_cycle_frame_heads set revision=h.revision+1,last_operation_id=ent.operation_id,active_intent_id=null where merchant_id=site and worker_id=i.worker_id and frame_key=i.frame_key;
 perform public.faolla_attendance_cycle_operation_proof_v1(op);
end;
$$;

create or replace function public.faolla_attendance_operational_cycle_send_v1(p_query jsonb,p_auth_user_id uuid,p_command jsonb,p_artifact jsonb,p_intent jsonb,p_allow_write boolean default false)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare fp text;site text;opid uuid;a public.merchant_attendance_period_cycle_adoptions%rowtype;op public.merchant_attendance_cycle_operations%rowtype;ent public.merchant_attendance_period_entries%rowtype;unused jsonb;
begin
 fp:=public.faolla_attendance_cycle_send_hash_v1(p_query,p_auth_user_id,p_command,p_intent);site:=p_query->>'siteId';opid:=(p_command->>'operationId')::uuid;
 select * into a from public.merchant_attendance_period_cycle_adoptions where merchant_id=site and send_operation_id=opid;
 if a.send_operation_id is not null then
  if a.actor_auth_user_id<>p_auth_user_id or a.query is distinct from p_query or a.command is distinct from p_command or a.intent is distinct from p_intent or a.command_fingerprint is distinct from fp then raise exception 'attendance_operation_conflict';end if;
 else
  --An old writer receipt is not evidence of 200 adoption. Never backfill it,
  --even with a valid current plan/source/owner. Leave original pending intact.
  if exists(select 1 from public.merchant_attendance_period_entries where merchant_id=site and operation_id=opid)
   or exists(select 1 from public.merchant_attendance_cycle_operations where merchant_id=site and operation_id=opid) then raise exception 'attendance_operation_conflict';end if;
  if p_allow_write is distinct from true then raise exception 'attendance_operational_cycle_disabled';end if;
  if p_query->>'access'='owner' then unused:=public.faolla_attendance_cycle_core_owner_v2(p_query,p_auth_user_id,p_command,p_artifact,p_allow_write,p_intent);
  else unused:=public.faolla_attendance_cycle_core_delegate_v1(p_query,p_auth_user_id,p_command,p_artifact,p_allow_write,p_intent);end if;
  select * into a from public.merchant_attendance_period_cycle_adoptions where merchant_id=site and send_operation_id=opid;
  if a.send_operation_id is null then raise exception 'attendance_operational_cycle_invalid';end if;
 end if;
 select * into op from public.merchant_attendance_cycle_operations where merchant_id=site and operation_id=opid;
 perform public.faolla_attendance_cycle_operation_proof_v1(op);
 select * into ent from public.merchant_attendance_period_entries where merchant_id=site and operation_id=opid;
 --Do not read today's report, archived body, grant directory or current source
 --for an original actor who has since lost authority. Only the saved minimal
 --old entry DTO plus the matched cycle receipt leave this recovery path.
 return jsonb_build_object('protocol','attendance-operational-cycle-v1','siteId',site,'actorId',p_auth_user_id,'readAt',public.faolla_attendance_cycle_stamp_v1(clock_timestamp()),
  'data',jsonb_build_object('kind','linked','periodOperation',public.faolla_attendance_period_entry_v2(ent)),'receipt',public.faolla_attendance_cycle_receipt_v1(op));
end;
$$;

--Explicit GET recovery has no command/reason in its URL. It never invokes a
--writer or current authority/source and cannot retrofit an old unlinked send.
create or replace function public.faolla_attendance_operational_cycle_send_recover_v1(p_query jsonb,p_auth_user_id uuid,p_intent jsonb,p_expected_fingerprint text)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare site text;opid uuid;k text;detail_query jsonb;common jsonb;fp text;
 a public.merchant_attendance_period_cycle_adoptions%rowtype;op public.merchant_attendance_cycle_operations%rowtype;ent public.merchant_attendance_period_entries%rowtype;
begin
 if p_auth_user_id is null or octet_length(p_query::text)>2048 or p_query->>'mode' is distinct from 'recover'
  or p_query->>'access' is null or p_query->>'access' not in('owner','delegate')
  or public.faolla_attendance_operational_rule_object_v1(p_query,array['siteId','access','workerId','fromDate','throughDate','mode','periodId','operationId','version','cursor']||(case when p_query->>'access'='delegate' then array['grantId'] else array[]::text[] end)) is distinct from true
  or p_query->'version' is distinct from 'null'::jsonb or p_query->'cursor' is distinct from 'null'::jsonb
  or public.faolla_attendance_operational_rule_scalar_v1(p_query->'periodId','uuid') is distinct from true
  or public.faolla_attendance_operational_rule_scalar_v1(p_query->'operationId','uuid') is distinct from true
  or public.faolla_attendance_operational_rule_object_v1(p_intent,array['intentId','expectedIntentFingerprint']) is distinct from true
  or public.faolla_attendance_operational_rule_scalar_v1(p_intent->'intentId','uuid') is distinct from true
  or public.faolla_attendance_operational_rule_scalar_v1(p_intent->'expectedIntentFingerprint','hash') is distinct from true
  or public.faolla_attendance_operational_rule_scalar_v1(to_jsonb(p_expected_fingerprint),'hash') is distinct from true then raise exception 'attendance_invalid_request';end if;
 perform public.faolla_attendance_cycle_query_v1(jsonb_build_object('siteId',p_query->'siteId','access',p_query->'access','workerId',p_query->'workerId',
  'grantId',p_query->'grantId','mode','detail','intentId',p_intent->'intentId'));
 foreach k in array array['fromDate','throughDate'] loop
  if jsonb_typeof(p_query->k) is distinct from 'string' or length(p_query->>k)<>10 or (p_query->>k)!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   or (p_query->>k)::date::text is distinct from p_query->>k or (p_query->>k)::date not between date '2000-01-01' and date '2100-12-31' then raise exception 'attendance_invalid_request';end if;
 end loop;
 if (p_query->>'throughDate')::date-(p_query->>'fromDate')::date not between 0 and 30 then raise exception 'attendance_invalid_request';end if;
 site:=p_query->>'siteId';opid:=(p_query->>'operationId')::uuid;
 common:=jsonb_build_object('protocol','attendance-operational-cycle-v1','siteId',site,'actorId',p_auth_user_id,'readAt',public.faolla_attendance_cycle_stamp_v1(clock_timestamp()));
 select * into a from public.merchant_attendance_period_cycle_adoptions where merchant_id=site and send_operation_id=opid;
 if a.send_operation_id is null then return common||jsonb_build_object('data',jsonb_build_object('kind','receipt'),'receipt',null);end if;
 detail_query:=jsonb_set(jsonb_set(p_query,'{mode}','"detail"'::jsonb),'{operationId}','null'::jsonb);
 if a.actor_auth_user_id<>p_auth_user_id or a.query is distinct from detail_query or a.intent is distinct from p_intent
  or a.command_fingerprint is distinct from p_expected_fingerprint then raise exception 'attendance_operation_conflict';end if;
 fp:=public.faolla_attendance_cycle_send_hash_v1(a.query,p_auth_user_id,a.command,a.intent);
 if fp is distinct from p_expected_fingerprint then raise exception 'attendance_operational_cycle_invalid';end if;
 select * into op from public.merchant_attendance_cycle_operations where merchant_id=site and operation_id=opid;
 if op.operation_id is null or op.action<>'link' or op.intent_id is distinct from a.intent_id or op.period_id is distinct from a.period_id then raise exception 'attendance_operational_cycle_invalid';end if;
 perform public.faolla_attendance_cycle_operation_proof_v1(op);
 select * into ent from public.merchant_attendance_period_entries where merchant_id=site and operation_id=opid;
 return common||jsonb_build_object('data',jsonb_build_object('kind','linked','periodOperation',public.faolla_attendance_period_entry_v2(ent)),
  'receipt',public.faolla_attendance_cycle_receipt_v1(op));
exception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format or numeric_value_out_of_range then
 raise exception 'attendance_invalid_request';
end;
$$;

do $cycle_forward$
declare recipe jsonb;change_value jsonb;f regprocedure;source_value text;new_source text;ns text;owner_id oid;def text;before_fn pg_proc%rowtype;after_fn pg_proc%rowtype;
begin
 select n.nspname,c.relowner into ns,owner_id from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.oid='public.merchant_attendance_settings'::regclass;
 for recipe in select value from jsonb_array_elements($cycle_recipes$[
  {
    "file": "202610080183_merchant_attendance_period_continuation.sql",
    "name": "faolla_attendance_period_closure_v1",
    "types": "jsonb,uuid,jsonb,jsonb,boolean",
    "oldHash": "641b80264cb76a9f839950e443a7c1d6f43a0bc4f235250bcee8b145e7c69395",
    "core": null,
    "coreHash": null,
    "newHash": "a23466f44c7ef385c2d2e75362d3c5bfbbee66b03d956981604f09f77b7bca4b",
    "changes": [
      {
        "from": "      source_result:=public.faolla_attendance_period_closure_source_v1(source_query,p_auth_user_id);\n      --179 also blocks relevant unresolved outage reviews before a fresh send.",
        "to": "      source_result:=public.faolla_attendance_period_closure_source_v1(source_query,p_auth_user_id);\n      if is_new then perform public.faolla_attendance_cycle_gate_v1(site,wid,p_auth_user_id,access_name,null,first_day,last_day,source_result,null);\n      elsif null is not null then raise exception 'attendance_operational_cycle_changed';end if;\n      --179 also blocks relevant unresolved outage reviews before a fresh send."
      }
    ],
    "wrapper": "\ndeclare\n  site text;access_name text;mode_name text;wid uuid;pid uuid;op uuid;requested_version integer;first_day date;last_day date;action_name text;\n  s public.merchant_attendance_settings%rowtype;w public.merchant_attendance_workers%rowtype;e public.merchant_enterprise_employees%rowtype;r public.merchant_enterprise_roles%rowtype;\n  c public.merchant_attendance_period_closures%rowtype;listed public.merchant_attendance_period_closures%rowtype;\n  saved public.merchant_attendance_period_entries%rowtype;entry_row public.merchant_attendance_period_entries%rowtype;\n  a public.merchant_attendance_period_artifacts%rowtype;v public.merchant_attendance_period_versions%rowtype;\n  source_result jsonb;source_query jsonb;artifact_json jsonb;artifact_text text;artifact_size integer;common jsonb;history jsonb:='[]';items jsonb:='[]';summary jsonb;\n  replayed boolean:=false;changed boolean;is_new boolean;new_version boolean;now_at timestamptz;prior_at timestamptz;fmt text:='YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"';\n  n integer;bytes_total bigint;k text;self_employee uuid;expected_worker jsonb;expected_period jsonb;\nbegin\n  if p_auth_user_id is null or public.faolla_attendance_shift_rule_binding_object_v1(p_query,array['siteId','access','workerId','fromDate','throughDate','mode','periodId','operationId','version']) is distinct from true\n    or octet_length(p_query::text)>2048 then raise exception 'attendance_invalid_request';end if;\n  site:=p_query->>'siteId';access_name:=p_query->>'access';mode_name:=p_query->>'mode';\n  if jsonb_typeof(p_query->'siteId') is distinct from 'string' or jsonb_typeof(p_query->'access') is distinct from 'string'\n    or jsonb_typeof(p_query->'mode') is distinct from 'string' or length(site)<>8 or site!~'^[0-9]{8}$'\n    or access_name not in('owner','self') or mode_name not in('list','preview','detail','recover','export') then raise exception 'attendance_invalid_request';end if;\n  foreach k in array array['workerId','periodId','operationId'] loop\n    if k<>'workerId' and p_query->k='null'::jsonb then continue;end if;\n    if jsonb_typeof(p_query->k) is distinct from 'string' or length(p_query->>k)<>36\n      or (p_query->>k)!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'attendance_invalid_request';end if;\n  end loop;\n  foreach k in array array['fromDate','throughDate'] loop\n    if jsonb_typeof(p_query->k) is distinct from 'string' or length(p_query->>k)<>10 or (p_query->>k)!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'\n      or (p_query->>k)::date::text is distinct from p_query->>k then raise exception 'attendance_invalid_request';end if;\n  end loop;\n  wid:=(p_query->>'workerId')::uuid;pid:=(p_query->>'periodId')::uuid;op:=(p_query->>'operationId')::uuid;\n  first_day:=(p_query->>'fromDate')::date;last_day:=(p_query->>'throughDate')::date;\n  if first_day<date '2000-01-01' or last_day>date '2100-12-31' or last_day-first_day not between 0 and 30 then raise exception 'attendance_invalid_request';end if;\n  if p_query->'version'<>'null'::jsonb then\n    if jsonb_typeof(p_query->'version') is distinct from 'number' or (p_query->>'version')!~'^[1-9][0-9]?$' then raise exception 'attendance_invalid_request';end if;\n    requested_version:=(p_query->>'version')::integer;\n    if requested_version>20 then raise exception 'attendance_invalid_request';end if;\n  end if;\n  if mode_name='list' and (pid is not null or op is not null or requested_version is not null)\n    or mode_name='preview' and (op is not null or requested_version is not null)\n    or mode_name in('detail','recover','export') and pid is null\n    or (mode_name='recover')<>(op is not null) or mode_name='export' and requested_version is null then raise exception 'attendance_invalid_request';end if;\n  if p_command is not null then\n    if public.faolla_attendance_period_closure_command_v1(p_command) is distinct from true or mode_name<>'detail' or requested_version is not null\n      or p_command->>'periodId' is distinct from pid::text then raise exception 'attendance_invalid_request';end if;\n    action_name:=p_command->>'action';op:=(p_command->>'operationId')::uuid;\n    if (access_name='self')<>(action_name in('confirm','dispute')) then raise exception 'attendance_access_denied';end if;\n  end if;\n  if p_artifact is not null and action_name is distinct from 'send' then raise exception 'attendance_invalid_request';end if;\n\n  -- Same serialization boundary as every correction/missing writer and150.\n  perform 1 from public.merchants where id=site and (access_name='self' or user_id=p_auth_user_id) for share;\n  if not found then raise exception 'attendance_access_denied';end if;\n  --175 current-source reads must take settings UPDATE before worker UPDATE.\n  --Fixed export, recovery, historical detail and list keep their old read lock.\n  if p_command is null and mode_name<>'preview' and not(mode_name='detail' and p_query->'version'='null'::jsonb) then select * into s from public.merchant_attendance_settings where merchant_id=site for share;\n  else select * into s from public.merchant_attendance_settings where merchant_id=site for update;end if;\n  if not found then raise exception 'attendance_settings_required';end if;\n  if access_name='self' then\n    select id into self_employee from public.merchant_enterprise_employees where merchant_id=site and auth_user_id=p_auth_user_id;\n    if self_employee is null then raise exception 'attendance_access_denied';end if;\n  end if;\n  --148 itself uses worker UPDATE. Acquire that mode up front, never upgrade a\n  --held worker SHARE when preview/detail subsequently call148.\n  select * into w from public.merchant_attendance_workers where merchant_id=site and id=wid for update;\n  if not found then if access_name='self' then raise exception 'attendance_access_denied';else raise exception 'attendance_worker_not_found';end if;end if;\n  select * into e from public.merchant_enterprise_employees where merchant_id=site and id=w.employee_id for share;\n  if w.employee_id is null or e.id is null or e.auth_user_id is null then raise exception 'attendance_period_identity_changed';end if;\n  if access_name='self' then\n    if e.id<>self_employee or e.auth_user_id<>p_auth_user_id or e.status<>'active' then raise exception 'attendance_access_denied';end if;\n    select * into r from public.merchant_enterprise_roles where merchant_id=site and id=e.role_id for share;\n    if r.status is distinct from 'active' or public.faolla_valid_merchant_enterprise_permissions_v1(r.permissions) is distinct from true\n      or not('enterprise.view'=any(r.permissions)) or not('attendance.self.view'=any(r.permissions))\n      or mode_name='export' and not('attendance.self.export'=any(r.permissions)) then raise exception 'attendance_access_denied';end if;\n  end if;\n  source_query:=jsonb_build_object('siteId',site,'access',access_name,'workerId',wid,'fromDate',first_day,'throughDate',last_day,'periodId',pid);\n  if pid is not null then\n    select * into c from public.merchant_attendance_period_closures where merchant_id=site and period_id=pid;\n    if c.period_id is not null then\n      if c.worker_id<>wid or c.from_date<>first_day or c.through_date<>last_day then raise exception 'attendance_access_denied';end if;\n      if c.employee_id<>e.id or c.employee_auth_user_id<>e.auth_user_id then raise exception 'attendance_period_identity_changed';end if;\n    end if;\n  end if;\n  if op is not null then\n    select * into saved from public.merchant_attendance_period_entries where merchant_id=site and operation_id=op;\n    if saved.operation_id is not null then\n      if saved.period_id<>pid or saved.actor_auth_user_id<>p_auth_user_id then raise exception 'attendance_access_denied';end if;\n      if c.period_id is null then raise exception 'attendance_period_closure_invalid';end if;\n      if p_command is not null and saved.command is distinct from p_command then raise exception 'attendance_operation_conflict';end if;\n      replayed:=true;\n    elsif mode_name='recover' then raise exception 'attendance_operation_not_found';end if;\n  end if;\n\n  --183: never return a truncated v1 history or write a head v1 cannot parse.\n  --Existing safe heads retain the original v1 result and operation ordering.\n  if c.period_id is not null and (c.revision>100 or c.current_version>20) then\n    raise exception 'attendance_period_protocol_required';end if;\n  if mode_name='list' then\n    for listed in select * from public.merchant_attendance_period_closures where merchant_id=site and worker_id=wid\n      and from_date=first_day and through_date=last_day order by opened_at desc,period_id desc limit 21 loop\n      if listed.revision>100 or listed.current_version>20 then raise exception 'attendance_period_protocol_required';end if;\n      if jsonb_array_length(items)>=20 then raise exception 'attendance_period_limit';end if;\n      if listed.employee_id<>e.id or listed.employee_auth_user_id<>e.auth_user_id then raise exception 'attendance_period_identity_changed';end if;\n      select * into a from public.merchant_attendance_period_artifacts where merchant_id=site and period_id=listed.period_id\n        and artifact_id=(select artifact_id from public.merchant_attendance_period_versions where merchant_id=site and period_id=listed.period_id and version=listed.current_version);\n      items:=items||jsonb_build_array(public.faolla_attendance_period_summary_v1(listed,public.faolla_attendance_period_artifact_checked_v1(a)));\n    end loop;\n    return jsonb_build_object('protocol','period-closure-v1','siteId',site,'workerId',wid,'actorId',p_auth_user_id,'access',access_name,\n      'readAt',to_char(clock_timestamp() at time zone 'UTC',fmt),'kind','list','items',items);\n  end if;\n  if mode_name='preview' then\n    if pid is not null and c.period_id is null then raise exception 'attendance_period_not_found';end if;\n    if c.period_id is not null then\n      select * into a from public.merchant_attendance_period_artifacts where merchant_id=site and period_id=pid\n        and artifact_id=(select artifact_id from public.merchant_attendance_period_versions where merchant_id=site and period_id=pid and version=c.current_version);\n      summary:=public.faolla_attendance_period_summary_v1(c,public.faolla_attendance_period_artifact_checked_v1(a));\n    end if;\n    source_result:=public.faolla_attendance_period_closure_source_v1(source_query,p_auth_user_id);\n    return jsonb_build_object('protocol','period-closure-v1','siteId',site,'workerId',wid,'actorId',p_auth_user_id,'access',access_name,\n      'readAt',to_char(clock_timestamp() at time zone 'UTC',fmt),'kind','preview','period',summary,'source',source_result);\n  end if;\n\n  if p_command is not null and saved.operation_id is null then\n    -- Reopen only removes this independent gate, not084 or the old deadline.\n    -- It remains available to the current owner when the module is paused.\n    if action_name<>'reopen' and (not coalesce(p_allow_write,false) or not s.enabled) then raise exception 'attendance_platform_paused';end if;\n    if access_name='self' and not('attendance.self.request'=any(r.permissions)) then raise exception 'attendance_access_denied';end if;\n    is_new:=c.period_id is null;\n    if is_new and action_name<>'send' then raise exception 'attendance_period_not_found';end if;\n    if (p_command->>'expectedRevision')::integer<>coalesce(c.revision,0) or (p_command->>'expectedVersion')::integer<>coalesce(c.current_version,0) then raise exception 'attendance_version_conflict';end if;\n    if coalesce(c.revision,0)>=100 or coalesce(c.revision,0)>=99 and action_name<>'reopen' then raise exception 'attendance_period_limit';end if;\n    if action_name='send' then\n      if c.sealed then raise exception 'attendance_period_sealed';end if;\n      if p_artifact is null then raise exception 'attendance_invalid_request';end if;\n      source_result:=public.faolla_attendance_period_closure_source_v1(source_query,p_auth_user_id);\n      if is_new then perform public.faolla_attendance_cycle_gate_v1(site,wid,p_auth_user_id,access_name,null,first_day,last_day,source_result,null);\n      elsif null is not null then raise exception 'attendance_operational_cycle_changed';end if;\n      --179 also blocks relevant unresolved outage reviews before a fresh send.\n      --Other old blockers retain their old review/seal semantics.\n      if (source_result->'blockers' ? 'period_in_progress' or source_result->'blockers' ? 'unresolved_outage') then raise exception 'attendance_period_blocked';end if;\n      if source_result->>'sourceFingerprint' is distinct from p_command->>'expectedFingerprint'\n        or p_artifact->>'sourceFingerprint' is distinct from source_result->>'sourceFingerprint'\n        or p_artifact->'source' is distinct from source_result->'sourceCanonical' then raise exception 'attendance_period_source_changed';end if;\n      expected_worker:=jsonb_build_object('workerId',wid,'employeeId',e.id,'employeeAuthUserId',e.auth_user_id,'workerName',w.display_name,'workerNo',w.worker_no);\n      expected_period:=jsonb_build_object('fromDate',first_day,'throughDate',last_day,'timeZone',source_result->'timeZone','startAt',source_result->'fromAt','endAt',source_result->'toAt');\n      if p_artifact->'worker' is distinct from expected_worker or p_artifact->'period' is distinct from expected_period\n        or p_artifact->'dayBoundaries' is distinct from source_result->'dayBoundaries'\n        or p_artifact->'report'->>'access' is distinct from 'owner'\n        or p_artifact->'report'->'base'->>'workerId' is distinct from wid::text\n        or p_artifact->'report'->'base'->>'employeeId' is distinct from e.id::text\n        or p_artifact->'report'->'base'->>'fromAt' is distinct from source_result->>'fromAt'\n        or p_artifact->'report'->'base'->>'toAt' is distinct from source_result->>'toAt' then raise exception 'attendance_period_closure_invalid';end if;\n      -- Validate every fresh supplied body, even if this source fingerprint can\n      -- reuse an existing immutable artifact (or need no new logical version).\n      artifact_text:=p_artifact::text;artifact_size:=octet_length(convert_to(artifact_text,'UTF8'));\n      if artifact_size>2097152 then raise exception 'attendance_period_source_too_large';end if;\n      a.merchant_id:=site;a.period_id:=pid;a.artifact_id:=op;a.source_fingerprint:=source_result->>'sourceFingerprint';\n      a.artifact_text:=artifact_text;a.artifact_sha256:=encode(sha256(convert_to(artifact_text,'UTF8')),'hex');a.artifact_bytes:=artifact_size;\n      perform public.faolla_attendance_period_artifact_checked_v1(a);\n      if not is_new and expected_period is distinct from jsonb_build_object('fromDate',c.from_date,'throughDate',c.through_date,'timeZone',c.time_zone,\n        'startAt',to_char(c.start_at at time zone 'UTC',fmt),'endAt',to_char(c.end_at at time zone 'UTC',fmt)) then raise exception 'attendance_period_source_changed';end if;\n      now_at:=clock_timestamp();\n      if now_at<(source_result->>'readAt')::timestamptz or c.updated_at>now_at then raise exception 'attendance_version_conflict';end if;\n      if is_new then\n        if exists(select 1 from (select x.end_at from public.merchant_attendance_period_closures x\n          where x.merchant_id=site and x.worker_id=wid and x.start_at<(source_result->>'toAt')::timestamptz\n          order by x.start_at desc,x.period_id desc limit 1) predecessor\n          where predecessor.end_at>(source_result->>'fromAt')::timestamptz) then raise exception 'attendance_period_overlap';end if;\n        select count(*) into n from (select 1 from public.merchant_attendance_period_closures where merchant_id=site limit 1000) bounded;\n        if n>=1000 then raise exception 'attendance_period_limit';end if;\n        select count(*) into n from (select 1 from public.merchant_attendance_period_closures where merchant_id=site and worker_id=wid limit 200) bounded;\n        if n>=200 then raise exception 'attendance_period_limit';end if;\n        insert into public.merchant_attendance_period_closures(merchant_id,period_id,worker_id,employee_id,employee_auth_user_id,from_date,through_date,time_zone,start_at,end_at,\n          revision,current_version,state,sealed,confirmed_version,unresolved_dispute,opened_at,updated_at)\n          values(site,pid,wid,e.id,e.auth_user_id,first_day,last_day,source_result->>'timeZone',(source_result->>'fromAt')::timestamptz,(source_result->>'toAt')::timestamptz,\n            1,1,'review',false,null,false,now_at,now_at) returning * into c;\n        new_version:=true;\n      else\n        select * into v from public.merchant_attendance_period_versions where merchant_id=site and period_id=pid and version=c.current_version;\n        select * into a from public.merchant_attendance_period_artifacts where merchant_id=site and artifact_id=v.artifact_id;\n        artifact_json:=public.faolla_attendance_period_artifact_checked_v1(a);\n        if a.source_fingerprint=source_result->>'sourceFingerprint' and artifact_json->'source' is distinct from source_result->'sourceCanonical' then\n          raise exception 'attendance_period_closure_invalid';end if;\n        new_version:=c.state='open' or a.source_fingerprint<>source_result->>'sourceFingerprint';\n        if new_version and c.current_version>=20 then raise exception 'attendance_period_limit';end if;\n      end if;\n      if new_version then\n        select * into a from public.merchant_attendance_period_artifacts where merchant_id=site and period_id=pid and source_fingerprint=source_result->>'sourceFingerprint';\n        if a.artifact_id is null then\n          --183 INSERT trigger charges the unchanged shared64MiB budget atomically.\n          a.merchant_id:=site;a.period_id:=pid;a.artifact_id:=op;a.source_fingerprint:=source_result->>'sourceFingerprint';\n          a.artifact_text:=artifact_text;a.artifact_sha256:=encode(sha256(convert_to(artifact_text,'UTF8')),'hex');a.artifact_bytes:=artifact_size;a.recorded_at:=now_at;\n          perform public.faolla_attendance_period_artifact_checked_v1(a);\n          --Keep the v1 client's existing definite-rejection code; v2 exposes the new storage-specific code.\n          begin\n            insert into public.merchant_attendance_period_artifacts select (a).*;\n          exception when raise_exception then\n            if sqlerrm='attendance_period_storage_limit' then raise exception 'attendance_period_limit';else raise;end if;\n          end;\n        else\n          artifact_json:=public.faolla_attendance_period_artifact_checked_v1(a);\n          if artifact_json->'source' is distinct from source_result->'sourceCanonical' then raise exception 'attendance_period_closure_invalid';end if;\n        end if;\n        if not is_new then c.current_version:=c.current_version+1;end if;\n        insert into public.merchant_attendance_period_versions(merchant_id,period_id,version,artifact_id,operation_id,recorded_at)\n          values(site,pid,c.current_version,a.artifact_id,op,now_at);\n        c.confirmed_version:=null;c.state:=case when c.unresolved_dispute then 'disputed' else 'review' end;\n      end if;\n    else\n      select * into v from public.merchant_attendance_period_versions where merchant_id=site and period_id=pid and version=c.current_version;\n      select * into a from public.merchant_attendance_period_artifacts where merchant_id=site and period_id=pid and artifact_id=v.artifact_id;\n      artifact_json:=public.faolla_attendance_period_artifact_checked_v1(a);\n      if action_name in('confirm','seal') then\n        if c.sealed then raise exception 'attendance_period_sealed';end if;\n        if c.state='open' then raise exception 'attendance_period_not_confirmed';end if;\n        if p_command->>'expectedFingerprint' is distinct from a.source_fingerprint then raise exception 'attendance_period_source_changed';end if;\n        source_result:=public.faolla_attendance_period_closure_source_v1(source_query,p_auth_user_id);\n        if source_result->>'sourceFingerprint' is distinct from a.source_fingerprint\n          or source_result->'sourceCanonical' is distinct from artifact_json->'source' then raise exception 'attendance_period_source_changed';end if;\n        if action_name='confirm' then c.confirmed_version:=c.current_version;c.unresolved_dispute:=false;c.state:='confirmed';\n        else\n          if source_result->>'validation' is distinct from 'owner_checked' or source_result->'blockers' is distinct from '[]'::jsonb then raise exception 'attendance_period_blocked';end if;\n          if c.confirmed_version is distinct from c.current_version or c.unresolved_dispute then raise exception 'attendance_period_not_confirmed';end if;\n          c.sealed:=true;c.state:='sealed';\n        end if;\n      elsif action_name='dispute' then\n        c.unresolved_dispute:=true;if not c.sealed then c.state:='disputed';end if;\n      elsif action_name='reopen' then\n        if not c.sealed then raise exception 'attendance_period_not_sealed';end if;\n        c.sealed:=false;c.state:='open';c.confirmed_version:=null;\n      end if;\n      -- respond appends an owner explanation only; it cannot clear a dispute,\n      -- invent the employee's confirmation or rewrite a sealed version.\n      now_at:=clock_timestamp();\n      if c.updated_at>now_at or source_result is not null and now_at<(source_result->>'readAt')::timestamptz then raise exception 'attendance_version_conflict';end if;\n    end if;\n    c.revision:=(p_command->>'expectedRevision')::integer+1;c.updated_at:=now_at;\n    insert into public.merchant_attendance_period_entries(merchant_id,period_id,operation_id,revision,version,actor_auth_user_id,action,command,recorded_at)\n      values(site,pid,op,c.revision,c.current_version,p_auth_user_id,action_name,p_command,now_at) returning * into saved;\n    update public.merchant_attendance_period_closures set revision=c.revision,current_version=c.current_version,state=c.state,sealed=c.sealed,\n      confirmed_version=c.confirmed_version,unresolved_dispute=c.unresolved_dispute,updated_at=c.updated_at where merchant_id=site and period_id=pid;\n  end if;\n\n  if c.period_id is null then raise exception 'attendance_period_not_found';end if;\n  if requested_version is null then requested_version:=case when replayed then saved.version else c.current_version end;end if;\n  if replayed and requested_version<>saved.version then raise exception 'attendance_invalid_request';end if;\n  select * into v from public.merchant_attendance_period_versions where merchant_id=site and period_id=pid and version=requested_version;\n  if v.version is null then raise exception 'attendance_period_not_found';end if;\n  select * into a from public.merchant_attendance_period_artifacts where merchant_id=site and period_id=pid and artifact_id=v.artifact_id;\n  artifact_json:=public.faolla_attendance_period_artifact_checked_v1(a);\n  summary:=public.faolla_attendance_period_summary_v1(c,artifact_json);\n  for entry_row in select * from public.merchant_attendance_period_entries where merchant_id=site and period_id=pid order by revision limit 101 loop\n    if entry_row.revision<>jsonb_array_length(history)+1 or entry_row.version>c.current_version or entry_row.recorded_at<c.opened_at\n      or entry_row.recorded_at>c.updated_at or prior_at>entry_row.recorded_at then raise exception 'attendance_period_closure_invalid';end if;\n    history:=history||jsonb_build_array(public.faolla_attendance_period_entry_v1(entry_row));prior_at:=entry_row.recorded_at;\n  end loop;\n  if jsonb_array_length(history)<>c.revision then raise exception 'attendance_period_closure_invalid';end if;\n  select count(*) into n from public.merchant_attendance_period_versions where merchant_id=site and period_id=pid;\n  if n<>c.current_version then raise exception 'attendance_period_closure_invalid';end if;\n  -- Recovery, export, historical version reads and all completed writes return\n  -- the stored bytes without collecting current sources or consulting tzdata.\n  if p_command is null and mode_name='detail' and p_query->'version'='null'::jsonb then\n    begin\n      source_result:=public.faolla_attendance_period_closure_source_v1(source_query,p_auth_user_id);\n      changed:=source_result->>'sourceFingerprint' is distinct from a.source_fingerprint;\n    exception when raise_exception then\n      -- A current source that cannot now be collected does not erase a saved\n      -- archive or strand reopening. Authorization and unknown errors still fail.\n      if sqlerrm=any(array['attendance_period_source_invalid','attendance_period_source_too_large',\n        'attendance_period_source_identity_changed','attendance_period_identity_unproven',\n        'attendance_period_source_identity_unproven','attendance_report_invalid_data',\n        'attendance_report_too_large','attendance_report_reconciliation_required','attendance_session_invalid_records']) then\n        changed:=null;\n      else raise;end if;\n    end;\n  end if;\n  common:=jsonb_build_object('protocol','period-closure-v1','siteId',site,'workerId',wid,'actorId',p_auth_user_id,'access',access_name,\n    'readAt',to_char(clock_timestamp() at time zone 'UTC',fmt));\n  return common||jsonb_build_object('kind','detail','period',summary,'artifact',artifact_json,'artifactText',a.artifact_text,\n    'artifactSha256',a.artifact_sha256,'artifactBytes',a.artifact_bytes,'artifactVersion',requested_version,'history',history,\n    'sourceChanged',changed,'operation',public.faolla_attendance_period_entry_v1(saved),'replayed',replayed);\nexception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format or numeric_value_out_of_range then\n  raise exception 'attendance_invalid_request';\nend;\n"
